text:
Use `pg` pool. Key config:

```javascript
import { Pool } from 'pg';

const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Pool sizing
  max: 20,                  // max connections
  min: 2,                   // keep alive floor
  idleTimeoutMillis: 30000, // kill idle conn after 30s
  connectionTimeoutMillis: 2000, // fail fast if no conn in 2s

  // Optional but good
  allowExitOnIdle: true,    // let process exit cleanly
});

// Catch pool-level errors (dropped connections, etc.)
pool.on('error', (err, client) => {
  console.error('Idle client error:', err.message);
});

// Query helper — auto-release client
export async function query(text, params) {
  const start = Date.now();
  try {
    const res = await pool.query(text, params);
    console.debug('Query took', Date.now() - start, 'ms');
    return res;
  } catch (err) {
    console.error('Query error:', { text, error: err.message });
    throw err;
  }
}

// Transaction helper — manual acquire/release
export async function withTransaction(fn) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release(); // ALWAYS release — even on throw
  }
}
```

Usage:

```javascript
// Simple query
const { rows } = await query('SELECT * FROM users WHERE id = $1', [userId]);

// Transaction
await withTransaction(async (client) => {
  await client.query('UPDATE accounts SET balance = balance - $1 WHERE id = $2', [100, fromId]);
  await client.query('UPDATE accounts SET balance = balance + $1 WHERE id = $2', [100, toId]);
});
```

Key points:

- `connectionTimeoutMillis` — fail fast over hang forever. Set low (2-5s).
- `idleTimeoutMillis` — prevent stale conn buildup. 30s good default.
- `max` — rule of thumb: `num_cores * 2 + disk_spindles`. Don't go crazy high; Postgres chokes.
- `client.release()` in `finally` — skip this = pool drain → app hang.
- Pool-level `error` listener mandatory — unhandled emits crash Node.
